28		<style>
29			:root {
30				color-scheme: light dark;
31				--text: #1a1a1a;
32				--text-secondary: #555;
33				--background: #fff;
34				--accent: #0052a3;
35				--border: #e0e0e0;
36			}
37			@media (prefers-color-scheme: dark) {
38				:root {
39					--text: #e0e0e0;
40					--text-secondary: #a0a0a0;
41					--background: #121212;
42					--accent: #5fa3ff;
43					--border: #333;
44				}
45			}
46			*,
47			*::before,
48			*::after {
49				box-sizing: border-box;
50			}
51			html {
52				-webkit-text-size-adjust: 100%;
53				text-size-adjust: 100%;
54			}
55			@media (prefers-reduced-motion: no-preference) {
56				html {
57					scroll-behavior: smooth;
58				}
59				a {
60					transition: text-decoration-thickness 0.15s ease;
61				}
62				.skip-link {
63					transition: transform 0.15s ease;
64				}
65			}
66			body {
67				display: grid;
68				grid-template-rows: auto 1fr auto;
69				min-height: 100vh;
70				min-height: 100dvh;
71				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
72				font-size: 1rem;
73				line-height: 1.6;
74				max-width: 70ch;
75				margin: 0 auto;
76				padding: max(1.25rem, env(safe-area-inset-top)) max(1.25rem, env(safe-area-inset-right)) max(1.25rem, env(safe-area-inset-bottom)) max(1.25rem, env(safe-area-inset-left));
77				color: var(--text);
78				background: var(--background);
79			}
80			h1 {
81				color: var(--accent);
82				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
83				font-weight: 700;
84				line-height: 1.1;
85				text-wrap: balance;
86				margin: 0 0 1.5rem 0;
87				letter-spacing: -0.02em;
88			}
89			p {
90				text-wrap: pretty;
91				margin: 1rem 0;
92			}
93			a {
94				color: var(--accent);
95				text-underline-offset: 0.2em;
96				text-decoration-thickness: 2px;
97				text-decoration-skip-ink: auto;
98				font-weight: 500;
99			}
100			a:hover, a:active {
101				text-decoration-thickness: 3px;
102			}
103			:focus-visible {
104				outline: 2px solid var(--accent);
105				outline-offset: 2px;
106			}
107			.skip-link {
108				position: absolute;
109				left: 0;
110				top: 0;
111				transform: translateY(-100%);
112				background: var(--accent);
113				color: var(--background);
114				padding: 0.75rem 1.5rem;
115				z-index: 1000;
116				border-radius: 0 0 0.25rem 0;
117				font-weight: 600;
118				text-decoration: none;
119				display: inline-block;
120			}
121			.skip-link:focus {
122				transform: none;
123				outline: 3px solid var(--text);
124				outline-offset: -3px;
125			}
126			header {
127				padding-block: 1.5rem 0;
128			}
129			main {
130				padding: 1rem 0;
131			}
132			main:focus {
133				outline: none;
134			}
135			footer {
136				padding-block: 1.5rem;
137				margin-top: 3rem;
138				border-top: 1px solid var(--border);
139				font-size: 0.875rem;
140				color: var(--text-secondary);
141				text-align: center;
142			}
143			footer p {
144				margin: 0.5rem 0;
145			}
146			@media print {
147				.skip-link {
148					display: none;
149				}
150				body {
151					display: block;
152					min-height: 0;
153					max-width: none;
154					padding: 0;
155				}
156				a {
157					color: inherit;
158					text-decoration: underline;
159				}
160				a[href^="http"]::after {
161					content: " (" attr(href) ")";
162					font-size: 0.85em;
163					font-weight: normal;
164				}
165			}
166		</style>
167	</head>
168	<body>
169		<a class="skip-link" href="#main">Skip to content</a>
170		<header>
171			<h1>Welcome</h1>
172		</header>
173		<main id="main" tabindex="-1">
174			<p>This is a well-structured, accessible HTML5 document.</p>
175			<p>
176				It uses semantic landmarks, a skip link for keyboard navigation,
177				and CSS that adapts to your light or dark mode preference.
178			</p>
179			<p>
180				Text and link colors meet WCAG AA contrast in both themes, type scales
181				with your browser's font size, and motion respects your system settings.
182			</p>
183		</main>
184		<footer>
185			<p>&copy; 2026. All rights reserved.</p>
186		</footer>
187	</body>
188	</html>
